        if not root1:
            return root2
        if not root2:
            return root1
        from collections import deque
        root = TreeNode(root1.val + root2.val)
        q = deque([(root, root1, root2)])
        while q:
            node, n1, n2 = q.popleft()
            if n1.left or n2.left:
                if n1.left and n2.left:
                    node.left = TreeNode(n1.left.val + n2.left.val)
                    q.append((node.left, n1.left, n2.left))
                elif n1.left:
                    node.left = n1.left
                else:
                    node.left = n2.left
            if n1.right or n2.right:
                if n1.right and n2.right:
                    node.right = TreeNode(n1.right.val + n2.right.val)
                    q.append((node.right, n1.right, n2.right))
                elif n1.right:
                    node.right = n1.right
                else:
                    node.right = n2.right
        return root

